(() => {
'use strict';
const $=s=>document.querySelector(s),canvas=$('#cake'),ctx=canvas.getContext('2d');
const colours=['#ec729a','#85b995','#a78cd7','#e8ae56'],colourNames=['pink','green','purple','gold'];
const tools=[
{id:'icing',name:'Icing',icon:'〰',cost:0,space:0,description:'Pipe any line, loop or message.'},
{id:'sprinkles',name:'Sprinkles',icon:'✦',cost:25,space:12,description:'Draw trails of rainbow sprinkles.'},
{id:'fruit',name:'Strawberries',icon:'🍓',cost:45,space:43,description:'Arrange juicy little strawberries.'},
{id:'chocolate',name:'Chocolate curls',icon:'🍫',cost:60,space:39,description:'Swirl rich chocolate ribbons.'},
{id:'flowers',name:'Sugar flowers',icon:'🌸',cost:75,space:45,description:'Bloom a garden on your cake.'},
{id:'candles',name:'Candles',icon:'🕯',cost:90,space:42,description:'Make a colourful birthday wish.'},
{id:'pearls',name:'Icing pearls',icon:'●',cost:110,space:20,description:'Draw elegant strings of sugar pearls.'}];
const occasions=[['Birthday cake','It’s my birthday!'],['Wedding cake','We’re getting married!'],['Anniversary cake','It’s our anniversary!'],['Graduation cake','I’m graduating!'],['Thank-you cake','A treat for someone kind.'],['Welcome cake','We have a new neighbour!']];
const names=['Bonnie Bunny','Bruno Bear','Cleo Cat','Finn Fox'];
const speech={welcome:'Welcome to your little bakery! Meet your customer and accept an order.',trace:'Start at the green star and follow the dots.',decorate:'Lovely icing! Choose a decorating tool, then draw on your cake. Serve it when you are ready.',served:'Thank you! What a beautiful cake!'};
const load=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}};
const old=load('magic-icing-bakery',{}),profile={coins:Number.isSafeInteger(old.coins)&&old.coins>=0?old.coins:0,served:Number.isSafeInteger(old.served)&&old.served>=0?old.served:0,unlocked:['icing',...tools.slice(1).map(t=>t.id).filter(id=>Array.isArray(old.unlocked)&&old.unlocked.includes(id))]};
let album=load('magic-icing-cakes',[]);if(!Array.isArray(album))album=[];album=album.filter(c=>c&&typeof c.image==='string'&&c.image.startsWith('data:image/')&&typeof c.name==='string').slice(-12);
const state={mode:'welcome',level:1,colour:0,tool:'icing',progress:0,points:[],decorations:[],active:null,action:null,last:null,order:null,traceColour:0,paused:false,muted:false,elapsed:0,time:0,reward:0};
const level=Number(new URLSearchParams(location.search).get('level'));if([1,2,3].includes(level))state.level=level;$('#level').value=String(state.level);
const art={};for(const name of ['bakery','counter','customers']){const im=new Image();im.onload=draw;im.src='assets/'+name+'.webp';art[name]=im;}
const servedImage=new Image();servedImage.onload=draw;
function cancel(){window.ClassroomVoice?.cancel();}
async function say(text){if(!state.muted&&!state.paused)return await window.ClassroomVoice?.speak(text);}
function storeProfile(){try{localStorage.setItem('magic-icing-bakery',JSON.stringify(profile));}catch{}}
function persist(){if(!['trace','decorate'].includes(state.mode))return;try{localStorage.setItem('magic-icing-draft',JSON.stringify({order:state.order,level:state.level,colour:state.colour,traceColour:state.traceColour,tool:state.tool,progress:state.progress,decorations:state.decorations,mode:state.mode}));}catch{}}
function clearDraft(){try{localStorage.removeItem('magic-icing-draft');}catch{}}
function stopPointer(){state.active=null;state.action=null;state.last=null;}
function overlay(html,kind=''){cancel();stopPointer();$('#overlay').className='overlay '+kind;$('#overlay').innerHTML='<div class="panel">'+html+'</div>';$('#overlay').hidden=false;draw();}
function close(){$('#overlay').hidden=true;}
function button(id,text,primary=false){return '<button id="'+id+'" class="'+(primary?'primary':'')+'">'+text+'</button>';}
function tool(id){return tools.find(t=>t.id===id)||tools[0];}
function buildPath(n,level){const pts=[],amp=level===1?62:level===2?82:98;for(let i=0;i<=360;i++){const t=i/360,x=255+690*t;let y=410;if(n===1)y=450-Math.sin(Math.PI*t)*amp*1.6;if(n===2)y=410+Math.sin(t*Math.PI*4)*amp;if(n===3){const p=t*4;y=410+(2*Math.abs(2*(p-Math.floor(p+.5)))-1)*amp;}if(n===4){const a=t*Math.PI*6;pts.push([285+630*t-32*Math.sin(a),410+amp*Math.sin(a)]);continue;}if(n===5){const a=t*Math.PI*4.5,r=148*(1-t)+18;pts.push([600+Math.cos(a)*r*1.6,410+Math.sin(a)*r]);continue;}pts.push([x,y]);}return pts;}
function makeOrder(){const i=profile.served;return {number:i+1,occasion:i%6,customer:i%4,colour:i%4,pattern:i%6,decoration:profile.unlocked[i%profile.unlocked.length]};}
function arrive(){cancel();stopPointer();state.mode='arriving';state.elapsed=0;state.order=makeOrder();state.points=[];state.decorations=[];close();update();draw();}
function orderSpeech(){const o=state.order;return occasions[o.occasion][0]+'. Please use '+colourNames[o.colour]+' icing'+(o.decoration==='icing'?'.':' and '+tool(o.decoration).name.toLowerCase()+'.');}
function showOrder(){state.mode='order';state.elapsed=0;update();draw();say(orderSpeech());}
function accept(){if(state.mode!=='order')return;cancel();state.mode='trace';state.progress=0;state.traceColour=state.colour;state.points=buildPath(state.order.pattern,state.level);state.decorations=[];state.tool='icing';stopPointer();close();update();persist();draw();say(speech.trace);}
function matches(){if(!state.order)return {colour:false,decoration:false};return {colour:state.traceColour===state.order.colour||state.decorations.some(a=>a.tool==='icing'&&a.colour===state.order.colour),decoration:state.order.decoration==='icing'||state.decorations.some(a=>a.tool===state.order.decoration&&a.marks.length>0)};}
function updatePalette(){document.querySelectorAll('[data-colour]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.colour)===state.colour));}
function update(){const prep=['trace','decorate'].includes(state.mode),o=state.order;document.body.classList.toggle('preparing',prep);$('#coins').textContent=profile.coins;$('#cake-count').textContent=album.length;$('#order').textContent=o?'ORDER '+String(o.number).padStart(2,'0')+' · '+names[o.customer].toUpperCase():'YOUR LITTLE NEIGHBOURHOOD BAKERY';$('#recipe-name').textContent=o?occasions[o.occasion][0]:'Open for little celebrations';$('#serve').hidden=state.mode!=='decorate';$('#restart').hidden=!prep;$('#decorating-tools').hidden=!prep;$('.colours').hidden=!prep;$('.progress').hidden=!prep;$('#level').disabled=prep;$('#shop').disabled=['welcome','handoff'].includes(state.mode);$('#album').disabled=['welcome','handoff'].includes(state.mode);$('#progress').style.width=state.progress/360*100+'%';$('#hint').textContent=state.mode==='trace'?'First, follow the dots. Then design your cake!':state.mode==='decorate'?'Choose a tool. Draw, decorate, and serve when you’re happy.':state.mode==='arriving'?'Someone has a celebration coming up…':state.mode==='handoff'?'A lovely cake, on its way to a lovely celebration.':'Accept an order to start baking. 20 coins per cake + 10 for matching the order.';
$('#undo').disabled=state.mode!=='decorate'||!state.decorations.length;$('#tool-tray').innerHTML=tools.map(t=>'<button data-tool="'+t.id+'" aria-pressed="'+(state.tool===t.id)+'" '+(!profile.unlocked.includes(t.id)||state.mode==='trace'&&t.id!=='icing'?'disabled':'')+' title="'+t.description+'"><span>'+t.icon+'</span> '+t.name+(!profile.unlocked.includes(t.id)?' <small>🔒</small>':'')+'</button>').join('');
document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{if(state.mode!=='decorate'||!profile.unlocked.includes(b.dataset.tool)||state.paused||!$('#overlay').hidden)return;stopPointer();state.tool=b.dataset.tool;update();persist();});
$('#order-card').hidden=!['order','trace','decorate','handoff'].includes(state.mode);$('#order-card').className='order-card '+(prep?'ticket':state.mode==='handoff'?'receipt':'');
if(o){if(prep){const m=matches();$('#order-card').innerHTML='<span class="eyebrow">'+occasions[o.occasion][0]+'</span><div>'+((state.mode==='decorate'&&m.colour)?'✓ ':'○ ')+colourNames[o.colour]+' icing'+(o.decoration==='icing'?'':' · '+(m.decoration?'✓ ':'○ ')+tool(o.decoration).name)+'</div>';}else if(state.mode==='handoff')$('#order-card').innerHTML='<span class="eyebrow">THANK YOU, LITTLE BAKER!</span><h2>What a lovely cake!</h2><p>+ '+state.reward+' coins'+(state.reward===30?' · Order matched!':' · Made with love')+'</p>';else{$('#order-card').innerHTML='<span class="eyebrow">'+names[o.customer]+' says…</span><h2>'+occasions[o.occasion][1]+'</h2><p>Could you make a <strong>'+occasions[o.occasion][0].toLowerCase()+'</strong> with <strong>'+colourNames[o.colour]+' icing</strong>'+(o.decoration==='icing'?'':' and <strong>'+tool(o.decoration).name.toLowerCase()+'</strong>')+'?</p><div class="order-pay">20 coins + 10 matching bonus</div>'+button('accept','Accept order →',true);$('#accept').onclick=accept;}}}
function saveAlbum(){draw();album.push({name:occasions[state.order.occasion][0],image:canvas.toDataURL('image/webp',.48)});album=album.slice(-12);try{localStorage.setItem('magic-icing-cakes',JSON.stringify(album));}catch{album=album.slice(-6);try{localStorage.setItem('magic-icing-cakes',JSON.stringify(album));}catch{}}}
function serve(){if(state.mode!=='decorate'||state.paused||!$('#overlay').hidden)return;cancel();stopPointer();draw();servedImage.src=canvas.toDataURL('image/webp',.8);saveAlbum();const m=matches();state.reward=20+(m.colour&&m.decoration?10:0);profile.coins+=state.reward;profile.served++;storeProfile();clearDraft();state.mode='handoff';state.elapsed=0;update();draw();say(speech.served);}
function path(points,width,colour,offset=0){if(!points?.length)return;const pts=points.length===1?[points[0],[points[0][0]+.1,points[0][1]]]:points;ctx.beginPath();pts.forEach(([x,y],i)=>i?ctx.lineTo(x,y+offset):ctx.moveTo(x,y+offset));ctx.strokeStyle=colour;ctx.lineWidth=width;ctx.lineCap='round';ctx.lineJoin='round';ctx.stroke();}
function star(x,y,r,colour){ctx.beginPath();for(let i=0;i<10;i++){const a=-Math.PI/2+i*Math.PI/5,d=i%2?r*.45:r;ctx.lineTo(x+Math.cos(a)*d,y+Math.sin(a)*d);}ctx.closePath();ctx.fillStyle=colour;ctx.fill();}
function circle(x,y,r,fill){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=fill;ctx.fill();}
function marker(x,y,finish){ctx.save();ctx.shadowColor='#62412838';ctx.shadowBlur=12;circle(x,y,23,finish?'#e97e96':'#6baf8b');ctx.lineWidth=4;ctx.strokeStyle='#fffdf1';ctx.stroke();star(x,y,12,'#fffdf1');ctx.restore();}
function icing(points,colour,width=17){path(points,width+4,'#9c596036',4);path(points,width,colour);path(points.map(([x,y])=>[x,y-3]),4,'#fff7');}
function bag(x,y){ctx.save();ctx.translate(x+3,y-3);ctx.rotate(.3);ctx.shadowColor='#66453245';ctx.shadowBlur=9;ctx.beginPath();ctx.moveTo(0,0);ctx.quadraticCurveTo(-35,-60,-24,-94);ctx.quadraticCurveTo(3,-113,30,-90);ctx.quadraticCurveTo(45,-52,0,0);const g=ctx.createLinearGradient(-25,0,35,0);g.addColorStop(0,colours[state.colour]);g.addColorStop(.5,'#ffe2ed');g.addColorStop(1,colours[state.colour]);ctx.fillStyle=g;ctx.fill();ctx.shadowBlur=0;ctx.beginPath();ctx.moveTo(-9,-24);ctx.lineTo(13,-25);ctx.lineTo(0,0);ctx.closePath();ctx.fillStyle='#a4a4a1';ctx.fill();ctx.fillStyle='#fff9';ctx.fillRect(-17,-85,34,5);ctx.restore();}
function decoration(m,type,colour){ctx.save();ctx.translate(m.x,m.y);ctx.rotate(m.angle||0);ctx.shadowColor='#79503d33';ctx.shadowBlur=3;ctx.shadowOffsetY=3;
if(type==='sprinkles'){ctx.fillStyle=colours[m.tint%4];ctx.beginPath();ctx.roundRect(-6,-2.5,12,5,2);ctx.fill();}
if(type==='fruit'){ctx.fillStyle='#dc5470';ctx.beginPath();ctx.moveTo(0,17);ctx.bezierCurveTo(-30,0,-19,-25,0,-14);ctx.bezierCurveTo(20,-27,30,0,0,17);ctx.fill();ctx.shadowBlur=0;star(0,-16,13,'#629b67');for(let i=0;i<7;i++)circle(Math.sin(i*3)*9,-8+i*3,1.4,'#ffe79b');}
if(type==='chocolate'){ctx.strokeStyle='#623a2d';ctx.lineWidth=9;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-14,10);ctx.bezierCurveTo(27,4,21,-20,-4,-12);ctx.bezierCurveTo(-21,-3,-4,9,8,-1);ctx.stroke();ctx.strokeStyle='#ae7a53';ctx.lineWidth=2;ctx.stroke();}
if(type==='flowers'){for(let i=0;i<5;i++)circle(Math.sin(i*Math.PI*2/5)*10,Math.cos(i*Math.PI*2/5)*10,9,colours[colour]);circle(0,0,6,'#ffe296');circle(-2,-2,2,'#fff4d0');}
if(type==='candles'){ctx.fillStyle=colours[colour];ctx.beginPath();ctx.roundRect(-6,-12,12,34,3);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#fff9';ctx.lineWidth=3;for(let i=-8;i<20;i+=8){ctx.beginPath();ctx.moveTo(-5,i);ctx.lineTo(5,i+5);ctx.stroke();}ctx.strokeStyle='#775746';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-12);ctx.lineTo(0,-21);ctx.stroke();ctx.fillStyle='#f9b64d';ctx.beginPath();ctx.moveTo(0,-38);ctx.bezierCurveTo(-17,-18,16,-15,0,-38);ctx.fill();circle(0,-25,3,'#fff0a6');}
if(type==='pearls'){const g=ctx.createRadialGradient(-3,-4,1,0,0,9);g.addColorStop(0,'#fff');g.addColorStop(.5,'#fff1d8');g.addColorStop(1,'#d5ac89');circle(0,0,9,g);circle(-3,-4,2,'#fff');}ctx.restore();}
function drawKitchen(){if(art.bakery?.naturalWidth)ctx.drawImage(art.bakery,0,0,1200,800);else{ctx.fillStyle='#f7e4c4';ctx.fillRect(0,0,1200,800);}if(!state.points.length)return;if(state.mode==='trace'){ctx.save();ctx.setLineDash([1,18]);path(state.points,5,'#ad9181');ctx.restore();}if(state.progress)icing(state.points.slice(0,state.progress+1),colours[state.mode==='trace'?state.colour:state.traceColour],19);for(const a of state.decorations){if(a.tool==='icing')icing(a.points,colours[a.colour],13);else for(const m of a.marks)decoration(m,a.tool,a.colour);}if(state.mode==='trace'){marker(...state.points.at(-1),true);marker(...state.points[state.progress],false);}if(state.active!==null&&state.last&&state.tool==='icing')bag(...state.last);}
function drawCustomer(x,y){const im=art.customers;if(!im?.naturalWidth)return;const sw=im.naturalWidth/2,sh=im.naturalHeight/2,i=state.order?.customer||0,h=445,w=h*sw/sh;ctx.drawImage(im,(i%2)*sw,Math.floor(i/2)*sh,sw,sh,x-w/2,y,w,h);}
function drawServedCake(x,y,w){if(!servedImage.naturalWidth)return;ctx.save();ctx.shadowColor='#6b44354d';ctx.shadowBlur=18;ctx.fillStyle='#fff5e5';ctx.beginPath();ctx.roundRect(x-8,y-8,w+16,w*.57+16,20);ctx.fill();ctx.beginPath();ctx.roundRect(x,y,w,w*.57,15);ctx.clip();ctx.drawImage(servedImage,150,145,915,520,x,y,w,w*.57);ctx.restore();}
function drawCounter(){const im=art.counter;if(im?.naturalWidth)ctx.drawImage(im,0,0,1200,800);else{ctx.fillStyle='#f5e7cf';ctx.fillRect(0,0,1200,800);ctx.fillStyle='#c68e63';ctx.fillRect(0,540,1200,260);}let x=820,y=118;if(state.mode==='arriving')x=820+(1-Math.min(1,state.elapsed/1000))*650;if(state.mode==='handoff'&&state.elapsed>1600)x=820+Math.min(1,(state.elapsed-1600)/1000)*650;drawCustomer(x,y+Math.sin(state.elapsed/130)*(['arriving','handoff'].includes(state.mode)?2:0));if(im?.naturalWidth)ctx.drawImage(im,0,im.naturalHeight*.674,im.naturalWidth,im.naturalHeight*.326,0,539.2,1200,260.8);if(state.mode==='handoff'){if(state.elapsed<1100)drawServedCake(655,560,320);else{const t=Math.min(1,(state.elapsed-1100)/500);const cy=560-t*110,cw=300-t*35;drawServedCake(x-140,cy,cw);const paw=['#f2dfbd','#cb9457','#e2a76b','#b87545'][state.order.customer];circle(x-128,cy+15,12,paw);circle(x-152+cw,cy+15,12,paw);}ctx.fillStyle='#fff2b4';ctx.font='bold 32px Trebuchet MS';ctx.textAlign='center';ctx.fillText('+'+state.reward+' coins',820,715);}}
function draw(){ctx.clearRect(0,0,1200,800);if(['trace','decorate'].includes(state.mode))drawKitchen();else drawCounter();}
function pos(e){const r=canvas.getBoundingClientRect();return [(e.clientX-r.left)*1200/r.width,(e.clientY-r.top)*800/r.height];}
function onCake(x,y){return x>220&&x<1005&&y>205&&y<590;}
function trace(x,y){const pts=state.points,tolerance=[0,29,22,16][state.level];let best=state.progress;for(let i=state.progress+1;i<=Math.min(360,state.progress+18);i++)if(Math.hypot(pts[i][0]-x,pts[i][1]-y)<=tolerance)best=i;if(best===state.progress)return;state.progress=best;state.last=[x,y];$('#progress').style.width=best/360*100+'%';if(best===360){stopPointer();state.traceColour=state.colour;state.mode='decorate';update();persist();say(speech.decorate);}draw();}
function stamp(x,y){const a=state.action;if(!a||a.marks.length>2000)return;if(a.tool==='sprinkles'){for(let i=0;i<3;i++){const seed=a.marks.length+i,sx=x+Math.sin(seed*2.4)*11,sy=y+Math.cos(seed*2.4)*11;if(onCake(sx,sy))a.marks.push({x:sx,y:sy,angle:seed*1.7,tint:seed%4});}}else a.marks.push({x,y,angle:a.tool==='candles'?0:Math.sin(a.marks.length*2.4)*.25,tint:0});}
function decorate(x,y){if(!onCake(x,y)){state.last=null;state.action=null;return;}if(!state.action){if(state.decorations.length>=300)return;state.action={tool:state.tool,colour:state.colour,points:[],marks:[]};state.decorations.push(state.action);state.last=null;}const a=state.action;if(a.tool==='icing'){if(a.points.length<6000)a.points.push([x,y]);state.last=[x,y];}else{const spacing=tool(a.tool).space;if(!state.last){stamp(x,y);state.last=[x,y];}else{let dx=x-state.last[0],dy=y-state.last[1],distance=Math.hypot(dx,dy);while(distance>=spacing){const px=state.last[0]+dx/distance*spacing,py=state.last[1]+dy/distance*spacing;stamp(px,py);state.last=[px,py];dx=x-px;dy=y-py;distance=Math.hypot(dx,dy);}}}draw();}
canvas.onpointerdown=e=>{if(state.paused||!$('#overlay').hidden||state.active!==null)return;const [x,y]=pos(e);if(state.mode==='trace'){const p=state.points[state.progress];if(Math.hypot(x-p[0],y-p[1])>[0,36,29,23][state.level])return;}else if(state.mode!=='decorate'||!onCake(x,y))return;state.active=e.pointerId;state.action=null;state.last=null;canvas.setPointerCapture(e.pointerId);e.preventDefault();if(state.mode==='trace')trace(x,y);else decorate(x,y);};
canvas.onpointermove=e=>{if(state.active!==e.pointerId||state.paused||!$('#overlay').hidden)return;const samples=e.getCoalescedEvents?.();for(const sample of samples?.length?samples:[e]){if(state.mode==='trace')trace(...pos(sample));else if(state.mode==='decorate')decorate(...pos(sample));}};
canvas.onpointerup=canvas.onpointercancel=()=>{stopPointer();persist();update();draw();};
function openShop(){if(state.paused||state.mode==='handoff')return;persist();overlay('<span class="eyebrow">A LITTLE SOMETHING FOR YOUR BAKERY</span><h2>Decoration cupboard</h2><p class="shop-balance">You have <b>'+profile.coins+' coins</b>. Unlock once, use forever.</p><div class="shop-grid">'+tools.slice(1).map(t=>'<article><span class="shop-icon">'+t.icon+'</span><h3>'+t.name+'</h3><p>'+t.description+'</p><button data-buy="'+t.id+'" '+(profile.unlocked.includes(t.id)||profile.coins<t.cost?'disabled':'')+'>'+(profile.unlocked.includes(t.id)?'✓ In your cupboard':'Unlock · '+t.cost+' coins')+'</button></article>').join('')+'</div>'+button('close-shop','Back to bakery',true),'shop-overlay');document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{const t=tool(b.dataset.buy);if(profile.unlocked.includes(t.id)||profile.coins<t.cost)return;profile.coins-=t.cost;profile.unlocked.push(t.id);storeProfile();update();openShop();});$('#close-shop').onclick=()=>{close();update();draw();};}
function showAlbum(){if(state.paused||state.mode==='handoff')return;persist();overlay('<span class="eyebrow">MADE WITH LOVE</span><h2>Your little cake collection</h2><div id="cake-shelf" class="cakes"></div>'+(!album.length?'<p>Your first customer is waiting!</p>':'')+button('close-album','Back to bakery',true));for(const c of album){const f=document.createElement('figure'),im=document.createElement('img'),cap=document.createElement('figcaption');im.src=c.image;im.alt=c.name;cap.textContent=c.name;f.append(im,cap);$('#cake-shelf').append(f);}$('#close-album').onclick=()=>{close();update();draw();};}
function pause(){if(state.paused){state.paused=false;close();$('#pause').textContent='Ⅱ';$('#pause').setAttribute('aria-label','Pause game');draw();return;}if(!$('#overlay').hidden)return;persist();state.paused=true;$('#pause').textContent='▶';$('#pause').setAttribute('aria-label','Resume game');overlay('<div class="big">☕</div><h2>A little bakery break.</h2><p>Your customer and cake will wait for you.</p>'+button('resume','Keep baking',true));$('#resume').onclick=pause;}
function restoreDraft(){const d=load('magic-icing-draft',null);if(!d||!d.order||d.order.number!==profile.served+1||!['trace','decorate'].includes(d.mode)||!Number.isInteger(d.order.pattern)||d.order.pattern<0||d.order.pattern>5||!occasions[d.order.occasion]||!names[d.order.customer]||!colourNames[d.order.colour]||!profile.unlocked.includes(d.order.decoration))return false;state.order=d.order;state.level=[1,2,3].includes(d.level)?d.level:1;state.colour=[0,1,2,3].includes(d.colour)?d.colour:0;state.traceColour=[0,1,2,3].includes(d.traceColour)?d.traceColour:state.colour;state.progress=Math.max(0,Math.min(360,Number(d.progress)||0));state.mode=state.progress===360?'decorate':'trace';state.tool=profile.unlocked.includes(d.tool)?d.tool:'icing';state.points=buildPath(state.order.pattern,state.level);state.decorations=Array.isArray(d.decorations)?d.decorations.filter(a=>a&&profile.unlocked.includes(a.tool)&&[0,1,2,3].includes(a.colour)&&Array.isArray(a.points)&&a.points.every(p=>Array.isArray(p)&&p.length===2&&p.every(Number.isFinite))&&Array.isArray(a.marks)&&a.marks.every(m=>m&&Number.isFinite(m.x)&&Number.isFinite(m.y))).slice(0,300):[];$('#level').value=String(state.level);close();updatePalette();update();draw();return true;}
document.querySelectorAll('[data-colour]').forEach(b=>b.onclick=()=>{if(state.paused||!['trace','decorate'].includes(state.mode)||!$('#overlay').hidden)return;stopPointer();state.colour=+b.dataset.colour;updatePalette();persist();update();draw();});
$('#serve').onclick=serve;$('#undo').onclick=()=>{if(state.mode!=='decorate'||state.paused||!$('#overlay').hidden)return;stopPointer();state.decorations.pop();persist();update();draw();};
$('#restart').onclick=()=>{if(state.paused||!['trace','decorate'].includes(state.mode))return;state.mode='order';accept();};
$('#level').onchange=()=>{if(['trace','decorate'].includes(state.mode))return;state.level=Number($('#level').value);};
$('#shop').onclick=openShop;$('#album').onclick=showAlbum;$('#pause').onclick=pause;
$('#sound').onclick=()=>{state.muted=!state.muted;$('#sound').textContent=state.muted?'♪ off':'♫';$('#sound').setAttribute('aria-pressed',state.muted);$('#sound').setAttribute('aria-label',state.muted?'Enable narration':'Mute narration');if(state.muted)cancel();else say(state.mode==='order'?orderSpeech():state.mode==='trace'?speech.trace:state.mode==='decorate'?speech.decorate:speech.welcome);};
$('#help').onclick=()=>{if(state.paused||!$('#overlay').hidden)return;persist();overlay('<h2>Welcome to the little bakery</h2><p>Accept a customer’s order. Follow the dots, then draw extra icing or choose an unlocked decorating tool. Hold and drag to sprinkle, arrange fruit, or add other treats. Undo removes your last stroke.</p><p>Serve your cake to earn 20 coins, plus 10 if you match the requested icing colour and decoration. Visit the shop to unlock more tools. Your money, tools and current cake are saved.</p>'+button('close-help','Let’s bake',true));$('#close-help').onclick=()=>{close();draw();};};
$('#fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.();};document.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='f'&&e.target.tagName!=='SELECT')$('#fullscreen').click();if(e.key==='Escape'&&state.paused)pause();});
document.addEventListener('visibilitychange',()=>{if(document.hidden){persist();cancel();stopPointer();if($('#overlay').hidden)pause();}});window.addEventListener('pagehide',()=>{persist();cancel();});$('#back').onclick=()=>{persist();cancel();};if(location.pathname.includes('/ois/')||new URLSearchParams(location.search).has('portal'))$('#back').href='../index.html?subject=english';
function advance(ms){if(state.paused||!$('#overlay').hidden)return;state.time+=ms;if(state.mode==='arriving'){state.elapsed+=ms;if(state.elapsed>=1000)showOrder();}else if(state.mode==='handoff'){state.elapsed+=ms;if(state.elapsed>=2800)arrive();}draw();}
window.advanceTime=advance;let previous=performance.now();function frame(now){advance(Math.min(80,now-previous));previous=now;requestAnimationFrame(frame);}requestAnimationFrame(frame);
window.render_game_to_text=()=>JSON.stringify({mode:state.mode,paused:state.paused,level:state.level,order:state.order?{...state.order,type:occasions[state.order.occasion][0],customerName:names[state.order.customer],colourName:colourNames[state.order.colour]}:null,tool:state.tool,colour:state.colour,traceColour:state.traceColour,progress:state.progress,total:360,nextPoint:state.points[state.progress],finish:state.points.at(-1),decorations:state.decorations.map(a=>({tool:a.tool,colour:a.colour,points:a.points.length,marks:a.marks.length})),coins:profile.coins,served:profile.served,unlocked:profile.unlocked,matching:matches(),collection:album.length,elapsed:state.elapsed,reward:state.reward,muted:state.muted,coordinates:'1200x800 canvas; origin top left, x right, y down; cake x220–1005, y205–590'});
// Handle touch button activation explicitly after a captured drawing gesture.
// A swipe along the tool tray still scrolls without selecting a tool.
let touchButton=null;
document.addEventListener('touchstart',e=>{const t=e.touches[0],b=e.target.closest('button');touchButton=t&&b?{button:b,x:t.clientX,y:t.clientY}:null;},{passive:true});
document.addEventListener('touchend',e=>{const t=e.changedTouches[0],start=touchButton;touchButton=null;if(!start||!t||start.button.disabled||!start.button.isConnected||Math.hypot(t.clientX-start.x,t.clientY-start.y)>12)return;e.preventDefault();start.button.click();},{passive:false});
document.addEventListener('touchcancel',()=>touchButton=null,{passive:true});
window.MagicIcing={getPath:()=>state.points.map(p=>[...p])};
update();draw();overlay('<div class="big">🍓</div><span class="eyebrow">YOUR LITTLE NEIGHBOURHOOD BAKERY</span><h2>Every cake has a story.</h2><p>Meet your customers, make their celebration cakes, and grow your decorating cupboard. Start with icing. See where a little imagination takes you.</p>'+button('begin',load('magic-icing-draft',null)?'Back to my bakery →':'Open my bakery →',true));$('#begin').onclick=()=>{close();if(!restoreDraft()){arrive();}else say(state.mode==='trace'?speech.trace:speech.decorate);};
})();

